From f9cad0b0faaf80d9b2c55bd45fc05909a3e0317f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 13:19:59 +0100
Subject: [PATCH] freespacenotifier: Offer to empty the trash when the disk is
 almost full

The low disk space warning only offered to open the drive or configure
it, even when trashed files were taking up space on that drive. It now
also shows an Empty Trash action whenever that trash isn't empty.

BUG: 109259
---
 freespacenotifier/CMakeLists.txt        |  1 +
 freespacenotifier/freespacenotifier.cpp | 33 +++++++++++++++++++++++++
 freespacenotifier/freespacenotifier.h   |  1 +
 3 files changed, 35 insertions(+)

diff --git a/freespacenotifier/CMakeLists.txt b/freespacenotifier/CMakeLists.txt
index fff143b68c..138ac99ab7 100644
--- a/freespacenotifier/CMakeLists.txt
+++ b/freespacenotifier/CMakeLists.txt
@@ -26,6 +26,7 @@ target_link_libraries(freespacenotifier
     KF6::I18n
     KF6::KIOCore
     KF6::KIOGui
+    KF6::KIOWidgets
     KF6::Notifications
     KF6::JobWidgets
     KF6::Service
diff --git a/freespacenotifier/freespacenotifier.cpp b/freespacenotifier/freespacenotifier.cpp
index 7feb8e40a6..c569a49def 100644
--- a/freespacenotifier/freespacenotifier.cpp
+++ b/freespacenotifier/freespacenotifier.cpp
@@ -10,10 +10,13 @@
 #include "freespacenotifier.h"
 #include "freespacenotifier_logging.h"

+#include <KConfig>
+#include <KConfigGroup>
 #include <KNotification>
 #include <KNotificationJobUiDelegate>

 #include <KIO/ApplicationLauncherJob>
+#include <KIO/DeleteOrTrashJob>
 #include <KIO/FileSystemFreeSpaceJob>
 #include <KIO/OpenUrlJob>

@@ -21,9 +24,13 @@
 #include <Solid/StorageAccess>

 #include <QFileInfo>
+#include <QStandardPaths>
+#include <QStorageInfo>

 #include <chrono>

+#include <unistd.h>
+
 #include "settings.h"

 FreeSpaceNotifier::FreeSpaceNotifier(const QString &udi, const QString &path, const KLocalizedString &notificationText, QObject *parent)
@@ -116,6 +123,16 @@ void FreeSpaceNotifier::checkFreeDiskSpace()
             m_notification->setComponentName(QStringLiteral("freespacenotifier"));
             m_notification->setText(text);

+            if (hasTrashOnDrive()) {
+                auto emptyTrashAction = m_notification->addAction(i18n("Empty Trash"));
+                connect(emptyTrashAction, &KNotificationAction::activated, this, [this] {
+                    using Iface = KIO::AskUserActionInterface;
+                    auto *job = new KIO::DeleteOrTrashJob({}, Iface::EmptyTrash, Iface::DefaultConfirmation, this);
+                    connect(job, &KJob::finished, this, &FreeSpaceNotifier::checkFreeDiskSpace);
+                    job->start();
+                });
+            }
+
             auto filelight = filelightService();
             if (filelight) {
                 auto filelightAction = m_notification->addAction(i18n("Open in Filelight"));
@@ -147,6 +164,22 @@ KService::Ptr FreeSpaceNotifier::filelightService() const
     return KService::serviceByDesktopName(QStringLiteral("org.kde.filelight"));
 }

+bool FreeSpaceNotifier::hasTrashOnDrive() const
+{
+    const KConfig trashConfig(QStringLiteral("trashrc"), KConfig::SimpleConfig);
+    if (trashConfig.group(QStringLiteral("Status")).readEntry("Empty", true)) {
+        return false;
+    }
+
+    const QString homeTrash = QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + QStringLiteral("/Trash");
+    if (QStorageInfo(homeTrash).rootPath() == QStorageInfo(m_path).rootPath()) {
+        return true;
+    }
+
+    const QString uid = QString::number(getuid());
+    return QFileInfo::exists(m_path + QStringLiteral("/.Trash-") + uid) || QFileInfo::exists(m_path + QStringLiteral("/.Trash/") + uid);
+}
+
 void FreeSpaceNotifier::exploreDrive(const QString &activationToken)
 {
     auto service = filelightService();
diff --git a/freespacenotifier/freespacenotifier.h b/freespacenotifier/freespacenotifier.h
index 477a611342..e4206d27ee 100644
--- a/freespacenotifier/freespacenotifier.h
+++ b/freespacenotifier/freespacenotifier.h
@@ -32,6 +32,7 @@ private:
     void checkFreeDiskSpace();
     void resetLastAvailable();

+    bool hasTrashOnDrive() const;
     KService::Ptr filelightService() const;
     void exploreDrive(const QString &activationToken);
     void onNotificationClosed();
